@page "/apply"
@rendermode InteractiveServer
@using sv_5fa535855c614c169d2472c666fdd04f.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2 class="mb-4">Job Application</h2>

    @* Step Indicator Bar *@
    <div class="step-indicator mb-4">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var stepIndex = i;
            var status = stepIndex < CurrentStep ? "completed"
                       : stepIndex == CurrentStep ? "active"
                       : "future";
            <div class="step-item @status"
                 @onclick="() => GoToStep(stepIndex)"
                 role="button"
                 tabindex="0">
                <div class="step-circle">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@_stepNames[stepIndex]</div>
            </div>
            @if (stepIndex < _stepNames.Length - 1)
            {
                <div class="step-connector @status"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger" role="alert">@ErrorMessage</div>
    }

    @* Step Content *@
    @switch (CurrentStep)
    {
        case 0:
            <ApplySteps.StepPersonalInfo
                FullName="@FullName" FullNameChanged="v => FullName = v"
                Email="@Email" EmailChanged="v => Email = v"
                Phone="@Phone" PhoneChanged="v => Phone = v"
                Address="@Address" AddressChanged="v => Address = v" />
            break;
        case 1:
            <ApplySteps.StepWorkHistory
                Entries="@WorkEntries"
                OnAddEntry="AddWorkEntry"
                OnRemoveEntry="RemoveWorkEntry" />
            break;
        case 2:
            <ApplySteps.StepReferences
                References="@References"
                OnAddReference="AddReference"
                OnRemoveReference="RemoveReference" />
            break;
        case 3:
            <ApplySteps.StepCoverLetter
                CoverLetter="@CoverLetter"
                CoverLetterChanged="v => CoverLetter = v"
                MaxLength="2000" />
            break;
        case 4:
            <ApplySteps.StepReview
                FullName="@FullName" Email="@Email" Phone="@Phone" Address="@Address"
                WorkEntries="@WorkEntries"
                References="@References"
                CoverLetter="@CoverLetter"
                OnEditSection="GoToStep" />
            break;
    }

    @* Navigation Buttons *@
    @if (!Submitted)
    {
        <div class="d-flex justify-content-between mt-4">
            <div>
                @if (CurrentStep > 0)
                {
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@IsProcessing">
                        &larr; Back
                    </button>
                }
            </div>
            <div>
                @if (CurrentStep < _stepNames.Length - 1)
                {
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Next &rarr;
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <span>Submitting…</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                }
            </div>
        </div>
    }

    @* Submission Confirmation *@
    @if (Submitted)
    {
        <div class="alert alert-success mt-4 text-center" role="alert">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your application ID is:</p>
            <p class="fs-3 fw-bold">#@SubmittedApplicationId</p>
            <p class="mb-0">We'll be in touch soon. Thank you!</p>
        </div>
    }
</div>

