@rendermode InteractiveServer
@using sv_5fa535855c614c169d2472c666fdd04f.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2 class="mb-4">Job Application</h2>

    @* Step Indicator Bar *@
    <div class="step-indicator mb-4">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var stepIndex = i;
            var status = stepIndex < CurrentStep ? "completed"
                       : stepIndex == CurrentStep ? "active"
                       : "future";
            <div class="step-item @status"
                 @onclick="() => GoToStep(stepIndex)"
                 role="button"
                 tabindex="0">
                <div class="step-circle">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@_stepNames[stepIndex]</div>
            </div>
            @if (stepIndex < _stepNames.Length - 1)
            {
                <div class="step-connector @status"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger" role="alert">@ErrorMessage</div>
    }

    @* Step Content *@
    @switch (CurrentStep)
    {
        case 0:
            <ApplySteps.StepPersonalInfo
                FullName="@FullName" FullNameChanged="v => FullName = v"
                Email="@Email" EmailChanged="v => Email = v"
                Phone="@Phone" PhoneChanged="v => Phone = v"
                Address="@Address" AddressChanged="v => Address = v" />
            break;
        case 1:
            <ApplySteps.StepWorkHistory
                Entries="@WorkEntries"
                OnAddEntry="AddWorkEntry"
                OnRemoveEntry="RemoveWorkEntry" />
            break;
        case 2:
            <ApplySteps.StepReferences
                References="@References"
                OnAddReference="AddReference"
                OnRemoveReference="RemoveReference" />
            break;
        case 3:
            <ApplySteps.StepCoverLetter
                CoverLetter="@CoverLetter"
                CoverLetterChanged="v => CoverLetter = v"
                MaxLength="2000" />
            break;
        case 4:
            <ApplySteps.StepReview
                FullName="@FullName" Email="@Email" Phone="@Phone" Address="@Address"
                WorkEntries="@WorkEntries"
                References="@References"
                CoverLetter="@CoverLetter"
                OnEditSection="GoToStep" />
            break;
    }

    @* Navigation Buttons *@
    @if (!Submitted)
    {
        <div class="d-flex justify-content-between mt-4">
            <div>
                @if (CurrentStep > 0)
                {
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@IsProcessing">
                        &larr; Back
                    </button>
                }
            </div>
            <div>
                @if (CurrentStep < _stepNames.Length - 1)
                {
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Next &rarr;
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <span>Submitting…</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                }
            </div>
        </div>
    }

    @* Submission Confirmation *@
    @if (Submitted)
    {
        <div class="alert alert-success mt-4 text-center" role="alert">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your application ID is:</p>
            <p class="fs-3 fw-bold">#@SubmittedApplicationId</p>
            <p class="mb-0">We'll be in touch soon. Thank you!</p>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int CurrentStep { get; set; }
    private string? ErrorMessage { get; set; }
    private bool IsProcessing { get; set; }
    private bool Submitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    // Step 1 — Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2 — Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = [new()];

    // Step 3 — References
    private List<ReferenceModel> References { get; set; } = [new(), new()];

    // Step 4 — Cover Letter
    private string CoverLetter { get; set; } = "";

    private void GoToStep(int step)
    {
        if (Submitted) return;
        if (step < CurrentStep)
        {
            ErrorMessage = null;
            CurrentStep = step;
        }
    }

    private async Task NextStep()
    {
        ErrorMessage = null;
        IsProcessing = true;
        try
        {
            if (!await ValidateCurrentStep()) return;
            CurrentStep++;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    private void PreviousStep()
    {
        ErrorMessage = null;
        if (CurrentStep > 0) CurrentStep--;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName))
                    { ErrorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(Email))
                    { ErrorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(Phone))
                    { ErrorMessage = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(Address))
                    { ErrorMessage = "Address is required."; return false; }
                var emailValid = await ApplicationService.ValidateEmailAsync(Email);
                if (!emailValid)
                    { ErrorMessage = "Please enter a valid email address."; return false; }
                break;
            case 1:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
                        { ErrorMessage = "Company name and job title are required for all entries."; return false; }
                    if (entry.StartDate == default)
                        { ErrorMessage = "Start date is required for all entries."; return false; }
                }
                break;
            case 2:
                foreach (var r in References)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
                        { ErrorMessage = "Name and email are required for all references."; return false; }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                    { ErrorMessage = "Please write a cover letter."; return false; }
                if (CoverLetter.Length > 2000)
                    { ErrorMessage = "Cover letter must be 2000 characters or fewer."; return false; }
                break;
        }
        return true;
    }

    private async Task SubmitApplication()
    {
        ErrorMessage = null;
        IsProcessing = true;
        try
        {
            var application = new JobApplication(
                new PersonalInfo(FullName, Email, Phone, Address),
                new WorkHistory(WorkEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate,
                    e.IsCurrent ? null : e.EndDate,
                    e.Description)).ToList()),
                References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                CoverLetter
            );
            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            Submitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsProcessing = false;
        }
    }

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(WorkEntryModel entry) { if (WorkEntries.Count > 1) WorkEntries.Remove(entry); }
    private void AddReference() { if (References.Count < 3) References.Add(new ReferenceModel()); }
    private void RemoveReference(ReferenceModel r) { if (References.Count > 1) References.Remove(r); }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
