toolArgs.file_text:
@using static sv_5fa535855c614c169d2472c666fdd04f.Components.Pages.Apply

<h4>References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var reference = References[i];
    var index = i + 1;
    <div class="reference-card">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <strong>Reference @index</strong>
            @if (References.Count > 1)
            {
                <button class="btn btn-sm btn-outline-danger" @onclick="() => OnRemoveReference.InvokeAsync(reference)">Remove</button>
            }
        </div>

        <div class="row mb-2">
            <div class="col-md-6">
                <label class="form-label">Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="reference.Name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input type="text" class="form-control" @bind="reference.Relationship" placeholder="e.g. Former Manager" />
            </div>
        </div>

        <div class="row mb-2">
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="reference.Email" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" @bind="reference.Phone" />
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary btn-sm" @onclick="() => OnAddReference.InvokeAsync()">
        + Add Reference
    </button>
}

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback OnAddReference { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnRemoveReference { get; set; }
}

@using static sv_5fa535855c614c169d2472c666fdd04f.Components.Pages.Apply

<h4>Review Your Application</h4>
<p class="text-muted">Please review your information before submitting.</p>

@* Personal Info *@
<div class="review-section">
    <h5>
        Personal Information
        <button class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
    </h5>
    <div class="row">
        <div class="col-md-6"><strong>Name:</strong> @FullName</div>
        <div class="col-md-6"><strong>Email:</strong> @Email</div>
        <div class="col-md-6"><strong>Phone:</strong> @Phone</div>
        <div class="col-md-6"><strong>Address:</strong> @Address</div>
    </div>
</div>

@* Work History *@
<div class="review-section">
    <h5>
        Work History
        <button class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
    </h5>
    @foreach (var entry in WorkEntries)
    {
        <div class="mb-2 ps-2 border-start border-3">
            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
            <span class="text-muted">
                @entry.StartDate.ToString("MMM yyyy") –
                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
            </span>
            @if (!string.IsNullOrWhiteSpace(entry.Description))
            {
                <p class="mb-0 mt-1">@entry.Description</p>
            }
        </div>
    }
</div>

@* References *@
<div class="review-section">
    <h5>
        References
        <button class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
    </h5>
    @foreach (var r in References)
    {
        <div class="mb-2">
            <strong>@r.Name</strong>
            @if (!string.IsNullOrWhiteSpace(r.Relationship))
            {
                <span class="text-muted">(@r.Relationship)</span>
            }
            <br />
            <span>@r.Email</span>
            @if (!string.IsNullOrWhiteSpace(r.Phone))
            {
                <span> · @r.Phone</span>
            }
        </div>
    }
</div>

@* Cover Letter *@
<div class="review-section">
    <h5>
        Cover Letter
        <button class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
    </h5>
    <p style="white-space: pre-wrap;">@CoverLetter</p>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
}

